interface Gateway {
  refund(chargeId: string, amountCents: number): Promise<{ id: string }>;
}

export async function issueRefund(
  gateway: Gateway,
  chargeId: string,
  amountCents: number,
): Promise<string | null> {
  try {
    const result = await gateway.refund(chargeId, amountCents);
    return result.id;
  } catch (ex) {
    return null;
  }
}

